import React, { useState } from 'react';
import {
  RefreshCw, DollarSign, ShoppingCart, Users, Clock, RotateCcw, Hash, Percent, TrendingUp,
  Package, BarChart3, AlertCircle, Pencil, Sparkles, Trash2, ArrowUp, ArrowDown, Plus, Undo2, Check,
} from 'lucide-react';
import { deleteKpi, reorderKpis, restoreKpiVersion, updateKpi } from '@/api';
import KpiEditorDrawer, { KpiDetailsDialog } from './KpiEditorDrawer';

// Business-user view of a generated KPI dashboard: one project, plain language, no database
// names, SQL errors or "generated by" details. Data shapes are the ones the KPI service
// guarantees: kpi_card -> [{VALUE}], bar/donut -> [{LABEL, VALUE}], line -> [{X, series...}].

const PALETTE = ['#1C58F6', '#10B981', '#F59E0B', '#8B5CF6', '#EF4444', '#06B6D4'];
const SECTION_ORDER = ['OVERVIEW', 'TRENDS', 'BREAKDOWN', 'DETAIL'];
const SECTION_LABELS = { OVERVIEW: 'Overview', TRENDS: 'Trends', BREAKDOWN: 'Breakdown', DETAIL: 'Details' };

const isCurrency = (kpi) => /\$|usd|eur|£|€/i.test(kpi.unit || '') ||
  /revenue|sales|amount|price|cost|spend|value|profit|gmv|aov/i.test(`${kpi.label} ${kpi.kpi_name}`);
const isPercent = (kpi) => /%|percent|pct/i.test(kpi.unit || '') || /rate|ratio|margin|%/i.test(kpi.label || '');

function compact(n, digits = 1) {
  const a = Math.abs(n);
  if (a >= 1e9) return `${(n / 1e9).toFixed(digits)}B`;
  if (a >= 1e6) return `${(n / 1e6).toFixed(digits)}M`;
  if (a >= 1e4) return `${(n / 1e3).toFixed(digits)}K`;
  return Number.isInteger(n) ? n.toLocaleString() : n.toLocaleString(undefined, { maximumFractionDigits: 2 });
}

function formatFor(kpi, v) {
  if (v === null || v === undefined || v === '') return '—';
  const n = Number(v);
  if (!Number.isFinite(n)) return String(v);
  if (isPercent(kpi)) return `${(Math.abs(n) <= 1 && !/%/.test(kpi.unit || '') ? n * 100 : n).toFixed(1)}%`;
  if (isCurrency(kpi)) return `${n < 0 ? '-' : ''}$${compact(Math.abs(n))}`;
  const unit = (kpi.unit || '').trim();
  const suffix = unit && !/^(rows?|count|#|number)$/i.test(unit) ? ` ${unit}` : '';
  return `${compact(n)}${suffix}`;
}

function iconFor(kpi) {
  const t = `${kpi.label} ${kpi.kpi_name} ${kpi.unit || ''}`.toLowerCase();
  if (/refund|return|cancel/.test(t)) return RotateCcw;
  if (/customer|user|buyer|client|member/.test(t)) return Users;
  if (/day|time|hour|duration|lead|delivery/.test(t)) return Clock;
  if (isPercent(kpi)) return Percent;
  if (isCurrency(kpi)) return DollarSign;
  if (/order|purchase|transaction|cart/.test(t)) return ShoppingCart;
  if (/product|item|sku|inventory|stock/.test(t)) return Package;
  if (/growth|trend/.test(t)) return TrendingUp;
  return Hash;
}

const prettyCol = (c) => String(c).toLowerCase().replace(/_/g, ' ').replace(/\b\w/g, (m) => m.toUpperCase());

function Shimmer({ className = '' }) {
  return <div className={`animate-pulse rounded-md bg-[#EEF2F7] ${className}`} />;
}

function EmptyChart({ failed }) {
  return (
    <div className="h-40 flex flex-col items-center justify-center text-center gap-1.5">
      <BarChart3 className="w-6 h-6 text-[#CBD5E1]" />
      <p className="text-[12px] text-[#94A3B8]">{failed ? "This figure couldn't be loaded" : 'No data for this period yet'}</p>
    </div>
  );
}

function Panel({ kpi, children, wide, controls }) {
  return (
    <div className={`relative bg-white border border-[#E2E8F0] rounded-2xl p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04)] ${wide ? 'lg:col-span-2' : ''}`}>
      {controls}
      <div className="mb-4 pr-2">
        <h4 className="text-[14px] font-semibold text-[#0F172A]">{kpi.label}</h4>
        {kpi.description && <p className="text-[12px] text-[#64748B] mt-0.5 line-clamp-1" title={kpi.description}>{kpi.description}</p>}
      </div>
      {children}
    </div>
  );
}

function KpiTile({ kpi, index, loading, controls }) {
  const icon = React.createElement(iconFor(kpi), { className: "w-4.5 h-4.5" });
  const color = PALETTE[index % PALETTE.length];
  const value = kpi.data?.[0]?.VALUE;
  return (
    <div className="relative overflow-hidden bg-white border border-[#E2E8F0] rounded-2xl p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04)] hover:shadow-md transition-shadow">
      <span className="absolute inset-x-0 top-0 h-1" style={{ backgroundColor: color }} />
      {controls}
      <div className="flex items-start justify-between gap-3">
        <p className="text-[12.5px] font-medium text-[#64748B] leading-snug line-clamp-2" title={kpi.label}>{kpi.label}</p>
        <span className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0" style={{ backgroundColor: `${color}14`, color }}>
          {icon}
        </span>
      </div>
      {loading && kpi.data === undefined ? (
        <Shimmer className="h-8 w-28 mt-3" />
      ) : (
        <p className="text-[28px] font-bold text-[#0F172A] tracking-tight mt-2 tabular-nums">{formatFor(kpi, value)}</p>
      )}
      {kpi.description && (
        <p className="text-[11.5px] text-[#94A3B8] mt-1.5 line-clamp-2 leading-snug" title={kpi.description}>{kpi.description}</p>
      )}
    </div>
  );
}

function Bars({ kpi }) {
  const rows = (kpi.data || []).slice(0, 10);
  if (!rows.length) return <EmptyChart failed={!!kpi.error} />;
  const max = Math.max(...rows.map((r) => Number(r.VALUE) || 0), 1);
  return (
    <div className="space-y-3">
      {rows.map((r, i) => (
        <div key={i}>
          <div className="flex items-center justify-between text-[12px] mb-1">
            <span className="text-[#334155] truncate pr-3" title={String(r.LABEL)}>{r.LABEL ?? '(blank)'}</span>
            <span className="font-semibold text-[#0F172A] tabular-nums shrink-0">{formatFor(kpi, r.VALUE)}</span>
          </div>
          <div className="h-2 bg-[#F1F5F9] rounded-full overflow-hidden">
            <div className="h-full rounded-full transition-all duration-700"
              style={{ width: `${Math.max(((Number(r.VALUE) || 0) / max) * 100, 1.5)}%`, backgroundColor: i === 0 ? PALETTE[0] : `${PALETTE[0]}${i < 3 ? 'B3' : '73'}` }} />
          </div>
        </div>
      ))}
    </div>
  );
}

function LineChart({ kpi }) {
  const [hover, setHover] = useState(null);
  const rows = kpi.data || [];
  if (!rows.length) return <EmptyChart failed={!!kpi.error} />;
  const keys = Object.keys(rows[0]).filter((k) => k !== 'X');
  const W = 600, H = 200, PL = 8, PR = 8, PT = 10, PB = 24;
  const vals = rows.flatMap((r) => keys.map((k) => Number(r[k]) || 0));
  const max = Math.max(...vals, 1), min = Math.min(0, ...vals);
  const x = (i) => PL + (rows.length === 1 ? (W - PL - PR) / 2 : (i / (rows.length - 1)) * (W - PL - PR));
  const y = (v) => PT + (1 - ((Number(v) || 0) - min) / (max - min || 1)) * (H - PT - PB);
  const label = (v) => String(v ?? '').slice(0, 10);
  const tickEvery = Math.max(1, Math.ceil(rows.length / 6));
  return (
    <div>
      {keys.length > 1 && (
        <div className="flex flex-wrap gap-3 mb-2">
          {keys.map((k, i) => (
            <span key={k} className="flex items-center gap-1.5 text-[11.5px] text-[#475569]">
              <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: PALETTE[i % PALETTE.length] }} />{prettyCol(k)}
            </span>
          ))}
        </div>
      )}
      <div className="relative">
        <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-52" preserveAspectRatio="none"
          onMouseLeave={() => setHover(null)}
          onMouseMove={(e) => {
            const r = e.currentTarget.getBoundingClientRect();
            const px = ((e.clientX - r.left) / r.width) * W;
            setHover(Math.min(rows.length - 1, Math.max(0, Math.round(((px - PL) / (W - PL - PR)) * (rows.length - 1)))));
          }}>
          <defs>
            {keys.map((k, i) => (
              <linearGradient key={k} id={`g-${kpi.kpi_name}-${i}`} x1="0" x2="0" y1="0" y2="1">
                <stop offset="0%" stopColor={PALETTE[i % PALETTE.length]} stopOpacity="0.22" />
                <stop offset="100%" stopColor={PALETTE[i % PALETTE.length]} stopOpacity="0" />
              </linearGradient>
            ))}
          </defs>
          {[0.25, 0.5, 0.75].map((f) => (
            <line key={f} x1={PL} x2={W - PR} y1={PT + f * (H - PT - PB)} y2={PT + f * (H - PT - PB)} stroke="#EEF2F7" />
          ))}
          <line x1={PL} x2={W - PR} y1={H - PB} y2={H - PB} stroke="#E2E8F0" />
          {keys.map((k, si) => {
            const pts = rows.map((r, i) => `${x(i)},${y(r[k])}`).join(' ');
            return (
              <g key={k}>
                {si === 0 && <polygon points={`${x(0)},${H - PB} ${pts} ${x(rows.length - 1)},${H - PB}`} fill={`url(#g-${kpi.kpi_name}-${si})`} />}
                <polyline points={pts} fill="none" stroke={PALETTE[si % PALETTE.length]} strokeWidth="2.25"
                  strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
              </g>
            );
          })}
          {hover !== null && <line x1={x(hover)} x2={x(hover)} y1={PT} y2={H - PB} stroke="#94A3B8" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />}
          {rows.map((r, i) => (i % tickEvery === 0 || i === rows.length - 1) && (
            <text key={i} x={x(i)} y={H - 6} fontSize="10" fill="#94A3B8"
              textAnchor={i === 0 ? 'start' : i === rows.length - 1 ? 'end' : 'middle'}>{label(r.X)}</text>
          ))}
        </svg>
        {hover !== null && (
          <div className="absolute top-0 pointer-events-none bg-[#0F172A] text-white rounded-lg px-2.5 py-1.5 text-[11px] shadow-lg"
            style={{ left: `${(x(hover) / W) * 100}%`, transform: `translateX(${hover > rows.length / 2 ? '-105%' : '5%'})` }}>
            <p className="text-[#94A3B8] mb-0.5">{String(rows[hover].X ?? '')}</p>
            {keys.map((k, i) => (
              <p key={k} className="tabular-nums"><span style={{ color: PALETTE[i % PALETTE.length] }}>●</span> {keys.length > 1 ? `${prettyCol(k)}: ` : ''}{formatFor(kpi, rows[hover][k])}</p>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function DataTable({ kpi }) {
  const rows = kpi.data || [];
  if (!rows.length) return <EmptyChart failed={!!kpi.error} />;
  const cols = Object.keys(rows[0]);
  const numeric = (v) => typeof v === 'number' || (v !== '' && v !== null && Number.isFinite(Number(v)) && !/^\d{4}-/.test(String(v)));
  return (
    <div className="max-h-80 overflow-auto rounded-xl border border-[#EEF2F7]">
      <table className="w-full text-left border-collapse">
        <thead className="sticky top-0 bg-[#F8FAFC]">
          <tr>{cols.map((c) => <th key={c} className="px-3 py-2.5 text-[11px] font-semibold text-[#64748B] whitespace-nowrap border-b border-[#E2E8F0]">{prettyCol(c)}</th>)}</tr>
        </thead>
        <tbody>
          {rows.slice(0, 50).map((r, i) => (
            <tr key={i} className="odd:bg-white even:bg-[#FAFBFD] hover:bg-[#F1F5FF]">
              {cols.map((c) => (
                <td key={c} className={`px-3 py-2 text-[12.5px] text-[#334155] whitespace-nowrap ${numeric(r[c]) ? 'text-right tabular-nums' : ''}`}>
                  {numeric(r[c]) ? Number(r[c]).toLocaleString(undefined, { maximumFractionDigits: 2 }) : String(r[c] ?? '')}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// One KPI rendered exactly as it appears on the dashboard — used for the "Add KPI" preview.
export function KpiPreview({ kpi }) {
  if (kpi.chart_type === 'kpi_card') return <KpiTile kpi={kpi} index={0} />;
  return (
    <Panel kpi={kpi}>
      {kpi.chart_type === 'line' ? <LineChart kpi={kpi} /> : kpi.chart_type === 'table' ? <DataTable kpi={kpi} /> : <Bars kpi={kpi} />}
    </Panel>
  );
}

function EditControls({ onEdit, onAi, onDelete, onUp, onDown }) {
  const btn = 'p-1.5 rounded-lg text-[#64748B] hover:bg-[#F1F5F9] hover:text-[#1C58F6] cursor-pointer disabled:opacity-30 disabled:cursor-default';
  return (
    <div className="absolute top-2 right-2 z-10 flex items-center gap-0.5 bg-white/95 border border-[#E2E8F0] rounded-xl shadow-sm px-1 py-0.5">
      <button className={btn} onClick={onUp} disabled={!onUp} title="Move earlier"><ArrowUp className="w-3.5 h-3.5" /></button>
      <button className={btn} onClick={onDown} disabled={!onDown} title="Move later"><ArrowDown className="w-3.5 h-3.5" /></button>
      <button className={btn} onClick={onEdit} title="Edit title and details"><Pencil className="w-3.5 h-3.5" /></button>
      <button className={btn} onClick={onAi} title="Change with AI"><Sparkles className="w-3.5 h-3.5" /></button>
      <button className={`${btn} hover:!text-[#DC2626]`} onClick={onDelete} title="Remove"><Trash2 className="w-3.5 h-3.5" /></button>
    </div>
  );
}

export default function ProjectDashboard({
  dashboard, projectName, loading, lastRefreshed, onRefresh, failed,
  // Editing: schemaId + conn (the saved connection payload) enable it; onChanged re-reads live values.
  schemaId, conn, onChanged,
}) {
  const [editing, setEditing] = useState(false);
  const [drawer, setDrawer] = useState(null); // { kpi? } — open "Add KPI" / "Change with AI"
  const [details, setDetails] = useState(null); // kpi being edited in the details dialog
  const [busy, setBusy] = useState(false);
  const [editError, setEditError] = useState('');
  const canEdit = !!(schemaId && conn && onChanged);

  const kpis = dashboard?.kpis || [];
  const anyFailed = failed || !!dashboard?.data_error || kpis.some((k) => k.error);
  const sections = SECTION_ORDER.map((id) => ({
    id,
    label: dashboard?.sections?.find((s) => s.id === id)?.label || SECTION_LABELS[id],
    kpis: kpis.filter((k) => (k.section || (k.chart_type === 'kpi_card' ? 'OVERVIEW' : 'BREAKDOWN')) === id),
  })).filter((s) => s.kpis.length);

  // Every change returns the saved dashboard (without values); re-read so the numbers show.
  const run = async (fn) => {
    setBusy(true);
    setEditError('');
    const res = await fn();
    setBusy(false);
    if (res.status !== 'success') {
      setEditError(res.message || 'That change could not be saved.');
      return res.message || 'That change could not be saved.';
    }
    onChanged();
    return null;
  };

  const move = (group, i, dir) => {
    const a = group[i], b = group[i + dir];
    const order = kpis.map((k) => k.kpi_name);
    const ia = order.indexOf(a.kpi_name), ib = order.indexOf(b.kpi_name);
    [order[ia], order[ib]] = [order[ib], order[ia]];
    run(() => reorderKpis(schemaId, order));
  };

  const remove = (kpi) => {
    if (window.confirm(`Remove “${kpi.label}” from the dashboard? You can undo this.`)) {
      run(() => deleteKpi(schemaId, kpi.kpi_name));
    }
  };

  const controlsFor = (group, i) => editing && (
    <EditControls
      onUp={i > 0 ? () => move(group, i, -1) : null}
      onDown={i < group.length - 1 ? () => move(group, i, 1) : null}
      onEdit={() => setDetails(group[i])}
      onAi={() => setDrawer({ kpi: group[i] })}
      onDelete={() => remove(group[i])}
    />
  );

  const headerBtn = 'px-4 py-2 rounded-xl text-[12.5px] font-semibold flex items-center gap-2 cursor-pointer disabled:opacity-50 transition-colors shadow-sm';

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-[22px] font-bold text-[#0F172A] tracking-tight">{projectName || 'Project'} Dashboard</h2>
          <p className="text-[12.5px] text-[#64748B] mt-1 flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${loading || busy ? 'bg-[#F59E0B] animate-pulse' : 'bg-[#10B981]'}`} />
            {busy ? 'Saving your change…' : loading ? 'Updating figures…' : lastRefreshed
              ? `Last updated ${lastRefreshed.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })}`
              : 'Live data'}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {editing ? (
            <>
              <button onClick={() => setDrawer({})} disabled={busy}
                className={`${headerBtn} bg-[#10338D] hover:bg-[#1C58F6] text-white`}>
                <Plus className="w-3.5 h-3.5" /> Add KPI
              </button>
              <button onClick={() => run(() => restoreKpiVersion(schemaId, conn))} disabled={busy}
                className={`${headerBtn} bg-white border border-[#CBD5E1] hover:border-[#1C58F6] text-[#334155]`}>
                <Undo2 className="w-3.5 h-3.5" /> Undo last change
              </button>
              <button onClick={() => { setEditing(false); setEditError(''); }} disabled={busy}
                className={`${headerBtn} bg-[#10B981] hover:bg-[#059669] text-white`}>
                <Check className="w-3.5 h-3.5" /> Done
              </button>
            </>
          ) : (
            <>
              {canEdit && (
                <button onClick={() => setEditing(true)}
                  className={`${headerBtn} bg-white border border-[#CBD5E1] hover:border-[#1C58F6] hover:text-[#1C58F6] text-[#334155]`}>
                  <Pencil className="w-3.5 h-3.5" /> Edit dashboard
                </button>
              )}
              <button onClick={onRefresh} disabled={loading}
                className={`${headerBtn} bg-white border border-[#CBD5E1] hover:border-[#1C58F6] hover:text-[#1C58F6] text-[#334155]`}>
                <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} /> Refresh
              </button>
            </>
          )}
        </div>
      </div>

      {editing && (
        <div className="flex items-center gap-2.5 rounded-xl px-4 py-3 bg-[#EEF3FF] border border-[#1C58F6]/25 text-[#10338D] text-[12.5px]">
          <Pencil className="w-4 h-4 shrink-0" />
          You're editing this project's dashboard — changes are saved right away and everyone on the project sees them.
        </div>
      )}

      {editError && (
        <div className="flex items-center gap-2.5 rounded-xl px-4 py-3 bg-[#FFFBEB] border border-[#FCD34D]/60 text-[#92400E] text-[12.5px]">
          <AlertCircle className="w-4 h-4 shrink-0" /> {editError}
        </div>
      )}

      {anyFailed && !loading && !editing && (
        <div className="flex items-center gap-2.5 rounded-xl px-4 py-3 bg-[#FFFBEB] border border-[#FCD34D]/60 text-[#92400E] text-[12.5px]">
          <AlertCircle className="w-4 h-4 shrink-0" /> Some figures couldn't be loaded — try Refresh.
        </div>
      )}

      {sections.map((s) => {
        const tiles = s.kpis.filter((k) => k.chart_type === 'kpi_card');
        const charts = s.kpis.filter((k) => k.chart_type !== 'kpi_card');
        return (
          <section key={s.id} className="space-y-3">
            <h3 className="text-[12px] font-semibold uppercase tracking-wider text-[#64748B]">{s.label}</h3>
            {tiles.length > 0 && (
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
                {tiles.map((k, i) => <KpiTile key={k.kpi_name} kpi={k} index={i} loading={loading} controls={controlsFor(tiles, i)} />)}
              </div>
            )}
            {charts.length > 0 && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {charts.map((k, i) => (
                  <Panel key={k.kpi_name} kpi={k} controls={controlsFor(charts, i)}
                    wide={k.chart_type === 'table' || (k.chart_type === 'line' && charts.length === 1)}>
                    {loading && k.data === undefined ? <Shimmer className="h-40 w-full" />
                      : k.chart_type === 'line' ? <LineChart kpi={k} />
                        : k.chart_type === 'table' ? <DataTable kpi={k} />
                          : <Bars kpi={k} />}
                  </Panel>
                ))}
              </div>
            )}
          </section>
        );
      })}

      {editing && kpis.length === 0 && (
        <div className="rounded-2xl border border-dashed border-[#CBD5E1] bg-white p-10 text-center text-[13px] text-[#64748B]">
          This dashboard is empty — click <strong>Add KPI</strong> to create your first one.
        </div>
      )}

      {drawer && (
        <KpiEditorDrawer
          schemaId={schemaId}
          conn={conn}
          editing={drawer.kpi}
          onClose={() => setDrawer(null)}
          onSaved={() => { setDrawer(null); onChanged(); }}
        />
      )}

      {details && (
        <KpiDetailsDialog
          kpi={details}
          schemaId={schemaId}
          conn={conn}
          onClose={() => setDetails(null)}
          onSaved={(dashboard) => { setDetails(null); onChanged?.(dashboard); }}
          onSave={async (changes) => {
            const err = await run(() => updateKpi(schemaId, details.kpi_name, changes));
            if (!err) setDetails(null);
            return err;
          }}
        />
      )}
    </div>
  );
}
